import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ASOF_PARAM } from '../../api/http';
import { AppSession } from '../../slots/defs/appSession';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useCurrentSheet, useCurrentUser, useSheetInfo } from './session';

// The as-of view of this screen (the `asof` search param; other users' screens are unaffected): while
// it is set, every read of the sheet gives it as it stood at the end of that date, the date standing in
// for its today, and every change is refused (api/http.ts). Setting or clearing it re-reads the sheet.
const isDate = (raw: string) => /^\d{4}-\d{2}-\d{2}$/.test(raw) && !Number.isNaN(Date.parse(`${raw}T00:00:00Z`));

function AsOfView() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setAsOf] = useSearchParam(ASOF_PARAM, asString);
  const info = useSheetInfo();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const shown = info.data?.id === sheet ? info.data : undefined;

  const change = async (next: string | undefined) => {
    await setAsOf(next);
    await queryClient.resetQueries({ queryKey: ['sheet', sheet] });
  };

  if (!user || !sheet) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (isDate(date.trim())) void change(date.trim());
      }}
    >
      <span>
        As of <strong data-testid="sheet-asof">{shown?.asOf ?? ''}</strong>
      </span>
      <input data-testid="asof-date" placeholder="YYYY-MM-DD" value={date} onChange={(e) => setDate(e.target.value)} />
      <button type="submit" data-testid="asof-set">
        Set as-of
      </button>
      <button type="button" data-testid="asof-clear" onClick={() => void change(undefined)}>
        Clear as-of
      </button>
    </form>
  );
}

export const contribution = AppSession.fill({ order: 25, Component: AsOfView });
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { useClaims } from '../claims/claims';
import { useSettings } from '../roles/roles';
import { useRates } from '../rates/rates';
import { personDue } from '../rates/due.slot';
import { gradeOn, usePeople } from './people';

// The export button: downloads every person on the sheet (retired people included, in list order) as CSV —
// name, grade in force on the sheet's today, retired-from date (blank when not retired) and due-total as shown.
export function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people.data ?? []) {
      lines.push([p.name, gradeOn(p, today), p.retiredFrom ?? '',
        personDue(p, claims.data ?? [], rates.data, today, settings.data)]);
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export people (CSV)
    </button>
  );
}

export const contribution = HomeMain.fill({ order: 19, Component: ExportPeople });
import { useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { csvValue } from '../people/export.slot';
import { poolsPath, poolsQueryKey, type Pool } from './pools';

// The pools export button: downloads the sheet's pools as CSV — pools in the order added, each pool's members in the
// order added — with pool, member (a member pool as pool:<name>), share and cut as the pool's row shows them (empty
// when none). The pools are re-read from the store first, so the cuts are current. Quoting and line ends as the
// people export.
function ExportPools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  if (!user || !sheet) return null;
  const download = async () => {
    const pools = await queryClient.fetchQuery({
      queryKey: poolsQueryKey(sheet),
      queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
      staleTime: 0,
    });
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of pools) {
      for (const m of p.members) {
        lines.push([p.name, m.poolId != null ? `pool:${m.name}` : m.name, m.share, m.cut]);
      }
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `pools-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <button type="button" data-testid="export-pools" onClick={() => { void download(); }}>
      Export pools (CSV)
    </button>
  );
}

export const contribution = HomeMain.fill({ order: 6.71, Component: ExportPools });
